--
-- Table structure for table `resources`
--

DROP TABLE IF EXISTS `resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resources` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `title` varchar(255) NOT NULL,
  `category_id` int(10) unsigned NOT NULL,
  `sub_category_id` int(10) unsigned DEFAULT NULL,
  `sub_category_text` varchar(100) DEFAULT NULL,
  `description` text NOT NULL,
  `author_or_instructor` varchar(150) NOT NULL,
  `unit_or_source` varchar(150) NOT NULL DEFAULT 'Sespimma Sespim Lemdiklat Polri',
  `lifecycle_status` enum('Draft','Diverifikasi','Dipublikasikan','Tidak Aktif','Arsip') NOT NULL DEFAULT 'Draft',
  `access_classification` enum('Terbuka','Internal','Terbatas','Metadata Saja') NOT NULL DEFAULT 'Internal',
  `has_digital_file` tinyint(1) NOT NULL DEFAULT 0,
  `file_format` enum('PDF','DOCX','PPTX','MP4','EPUB') DEFAULT NULL,
  `file_size_bytes` bigint(20) unsigned DEFAULT NULL,
  `file_size_label` varchar(20) DEFAULT NULL,
  `file_url` varchar(255) DEFAULT NULL,
  `physical_location` varchar(150) DEFAULT NULL,
  `created_by` bigint(20) unsigned NOT NULL DEFAULT 1,
  `verified_by` bigint(20) unsigned DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  KEY `fk_res_sub_category` (`sub_category_id`),
  KEY `fk_res_creator` (`created_by`),
  KEY `fk_res_verifier` (`verified_by`),
  KEY `idx_res_lifecycle_access` (`lifecycle_status`,`access_classification`),
  KEY `idx_res_category_status` (`category_id`,`lifecycle_status`),
  FULLTEXT KEY `ft_res_search` (`title`,`description`,`author_or_instructor`),
  CONSTRAINT `fk_res_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_res_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_res_sub_category` FOREIGN KEY (`sub_category_id`) REFERENCES `sub_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_res_verifier` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

