LOCK TABLES `resources` WRITE;
/*!40000 ALTER TABLE `resources` DISABLE KEYS */;
INSERT INTO `resources` VALUES (1,'res-hanjar-sespimma-01','Hanjar 01: Peran Polri dalam Optimalisasi Sektor Pangan',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025 mengenai strategi pengawalan, pengamanan terpadu, dan optimalisasi ketahanan pangan nasional.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.29 MB','/1. HANJAR SESPIMMA 2025 PERAN POLRI DALAM OPTIMALISASI SEKTOR PANGAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(2,'res-hanjar-sespimma-02','Hanjar 02: Manajemen Kehumasan Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Strategi komunikasi publik, manajemen media sosial, mitigasi krisis reputasi, dan penguatan transparansi institusi.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.93 MB','/2. HANJAR SESPIMMA 2025 MANAJAMEN KEHUMASAN POLRI.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(3,'res-hanjar-sespimma-03','Hanjar 03: Penanganan Tindak Pidana Narkoba (TP Narkoba)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Taktik penyelidikan peredaran gelap narkotika, clandestine lab, controlled delivery, dan pemutusan jaringan sindikat.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.19 MB','/3. HANJAR SESPIMMA 2025 TP NARKOBA.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(4,'res-hanjar-sespimma-04','Hanjar 04: Penanganan Tindak Pidana Perjudian Online (TP Judol)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Penindakan sindikat judi online lintas-negara, profiling rekening penampung, pemblokiran situs, dan penegakan hukum siber.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.38 MB','/4. HANJAR SESPIMMA 2025 TP JUDOL.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(5,'res-hanjar-sespimma-05','Hanjar 05: Manusia dan Peradaban',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Landasan filosofis, sosiologis, dan kultural hubungan manusia, peradaban hukum, dan pemolisian yang humanis.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.20 MB','/5. HANJAR SESPIMMA 2025 MANUSIA DAN PERADABAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(6,'res-hanjar-sespimma-06','Hanjar 06: Inovasi dan Kreatifitas Kepolisian',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Metodologi pengembangan inovasi pelayanan publik, creative thinking perwira polri, dan proyek perubahan institusional.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.24 MB','/6. HANJAR SESPIMMA 2025 INOVASI DAN KREATIFITAS.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(7,'res-hanjar-sespimma-07','Hanjar 07: Penanganan Tindak Pidana Korupsi (TP Korupsi)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Konstruksi hukum tipidkor, audit forensik kerugian keuangan negara, asset recovery, dan koordinasi KPK/Kejaksaan.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.91 MB','/7. HANJAR SESPIMMA 2025 TP KORUPSI.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(8,'res-hanjar-sespimma-08','Hanjar 08: Analisis SWOT dan Analytic Hierarchy Process (AHP)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Metode analisis kuantitatif dan kualitatif SWOT-AHP dalam perumusan kebijakan strategis dan Taskap perorangan serdik.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.72 MB','/8. HANJAR SESPIMMA 2025 ANALISIS SWOT DAN AHP.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(9,'res-hanjar-sespimma-09','Hanjar 09: Manajemen Keuangan Satker Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Tata kelola perbendaharaan DIPA, sistem akuntansi instansi, pertanggungjawaban keuangan dinas, dan kepatuhan anggaran.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.92 MB','/9. HANJAR SESPIMMA 2025 MANAJEMEN KEUANGAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(10,'res-hanjar-sespimma-10','Hanjar 10: Manajemen Logistik Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Siklus logistik kepolisian, manajemen pergudangan senpi & amunisi, pemeliharaan randis, dan inventarisasi BMN.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.90 MB','/10. HANJAR SESPIMMA 2025 MANAJEMEN LOGISTIK.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(11,'res-hanjar-sespimma-11','Hanjar 11: Penegakan HAM, Hukum, dan Keadilan',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Penerapan prinsip hak asasi manusia dalam tindakan kepolisian, due process of law, dan etika penegakan keadilan.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.05 MB','/11. HANJAR SESPIMMA 2025 PENEGAKAN HAM, HUKUM, DAN KEADILAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(12,'res-hanjar-sespimma-12','Hanjar 12: Manajemen & Standar Keberhasilan Fungsi Intelkam',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Tolok ukur keberhasilan operasional intelijen keamanan, deteksi dini kamtibmas, dan penyusunan produk intelijen strategis.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbatas',1,'PDF',NULL,'2.00 MB','/12. HANJAR SESPIMMA 2025 MNJMN & STNDR KEBERHASILAN FUNGSI INTELKAM.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(13,'res-hanjar-sespimma-13','Hanjar 13: Manajemen dan Standar Keberhasilan Fungsi Binmas',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Strategi pembinaan masyarakat, kemitraan Polmas, penguatan peran Bhabinkamtibmas, dan pemeliharaan harkamtibmas partisipatif.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.17 MB','/13. HANJAR SESPIMMA 2025 MANAJAMEN DAN STANDAR KEBERHASILAN FUNGSI BINMAS.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(14,'res-hanjar-sespimma-14','Hanjar 14: Manajemen Sumber Daya Manusia (SDM) Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Siklus pembinaan personel polri, penilaian kinerja berbasis 13 komponen, asesmen kompetensi, dan penegakan meritokrasi.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.30 MB','/14. HANJAR SESPIMMA 2025 MANAJEMEN SDM.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(15,'res-001','Hanjar Kepemimpinan Strategis Polri Modern di Era Digital',2,NULL,'Bahan Ajar Pokok','Materi pedoman implementasi strategi pemolisian visioner berbasis data dan integritas organisasi.','Kombes Pol. Dr. Hendra P