DROP TABLE IF EXISTS `user_profiles_gadik`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_profiles_gadik` (
  `user_id` bigint(20) unsigned NOT NULL,
  `no_urut_nominatif` int(10) unsigned DEFAULT NULL,
  `pangkat` enum('KOMBES POL','AKBP','KOMPOL','IPTU') NOT NULL,
  `jabatan` varchar(150) NOT NULL,
  `kategori_jabatan` enum('Anjak Madya','Widyaiswara Madya Tk. III','Gadik Madya','Widyaiswara Muda Tk. I','Widyaiswara Pratama Tk. I') NOT NULL,
  `agama` enum('ISLAM','KRISTEN','KATOLIK','HINDU','BUDDHA','KONGHUCU') NOT NULL DEFAULT 'ISLAM',
  `eselon` enum('II B3','III A2','III B','IV B') NOT NULL,
  `golongan` enum('IV-C','IV-B','IV-A','III-C','III-B') NOT NULL,
  `status_fungsional` varchar(50) NOT NULL DEFAULT 'Aktif Fungsional',
  `no_sprint` varchar(80) DEFAULT NULL,
  `bio` text DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `fk_gadik_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

