  `resource_id` bigint(20) unsigned NOT NULL,
  `verifier_id` bigint(20) unsigned NOT NULL,
  `status_before` varchar(30) NOT NULL,
  `status_after` varchar(30) NOT NULL,
  `action_result` enum('Disetujui','Revisi','Ditolak') NOT NULL,
