  PRIMARY KEY (`id`),
  KEY `fk_vl_verifier` (`verifier_id`),
  KEY `idx_vl_resource` (`resource_id`),
  CONSTRAINT `fk_vl_resource` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_vl_verifier` FOREIGN KEY (`verifier_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
